-- ============================================================
-- Go for the Throat: proc configuration and threat
-- ============================================================
--
-- NOTE what is NOT here any more: there are no spell_pet_auras rows.  The pet
-- aura is no longer permanent -- it is applied for 10s by the hunter's ranged
-- crit, through the talent's own Effect2 proc trigger, so nothing needs
-- delivering at summon time.
--
-- HitMask 0, deliberately.  This used to be 2 (PROC_HIT_CRITICAL) because the
-- bleed came off the PET's crits; now the crit requirement lives entirely on
-- the HUNTER's side (core's -34950 row, HitMask 2, which is untouched), and
-- every melee hit inside the frenzy window rends.
--
-- ProcFlags 20 = melee auto-attack | spell melee damage class, so Claw / Bite /
-- Gore count alongside white swings.
--
-- Cooldown 0: unlike Taste for Blood this is already bounded, by the 10s window
-- and by how often the hunter crits.  Worth watching all the same -- a fast pet
-- inside the window is the same shape of problem Taste for Blood turned out to
-- have.

DELETE FROM `spell_pet_auras` WHERE `aura` = 200760;
DELETE FROM `spell_proc` WHERE `SpellId` = 200760;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(200760, 0, 0, 0, 0, 0, 20, 0, 2, 0, 0, 0, 0, 100, 0, 0);

-- 0x8000 = SPELL_ATTR0_CU_IGNORE_ARMOR (SpellInfo.h:192).  The amount handed to
-- 200761 is already post-mitigation -- it is a share of a hit that landed -- so
-- running it through Unit::IsDamageReducedByArmor would tax it twice.

DELETE FROM `spell_custom_attr` WHERE `spell_id` = 200761;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) VALUES
(200761, 0x8000);

-- "a high amount of threat".  pctMod is the right dial because
-- ThreatManager::CalculateModifiedThreat (ThreatManager.cpp:704) applies it per
-- spell, so the bleed can be loud without its damage being large.
--
-- Mind the product: this 3.0 multiplies against the pet's own x2.00 from
-- Beastmaster's Bond (200743), because _singleSchoolModifiers is read off the
-- threat GENERATOR -- the pet.  Effective threat is therefore ~6x the bleed's
-- damage.  Tune THIS number rather than the damage; the damage is shared with
-- the visible tooltip.

DELETE FROM `spell_threat` WHERE `entry` = 200761;
INSERT INTO `spell_threat` (`entry`, `flatMod`, `pctMod`, `apPctMod`) VALUES
(200761, 0, 3, 0);

